INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z32-q40','nism-5a-z32','For tax purposes, an equity-oriented fund is one investing more than ___ in domestic listed equity shares.','["75%","65%","80%","50%"]',1,'A FoF of equity funds is treated as non-equity.',40) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z32-q41','nism-5a-z32','The Price Return Index captures:','["Price changes plus reinvested dividends","Price changes only","Dividends only","Interest only"]',1,'This gave schemes an unfair advantage over PRI.',41) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z32-q42','nism-5a-z32','A scheme announces a bonus of 1:4 (one free unit for every 4 units held). An investor holding 2800 units will receive:','["700 units","11200 units","560 units","2800 units"]',0,'Bonus units = 2800 ÷ 4.',42) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z32-q43','nism-5a-z32','A self-occupied home is NOT generally treated as an investment because:','["It cannot be mortgaged","It is exempt from asset allocation","It is always illiquid and therefore illegal as an asset","It does not generate income or capital gains for the owner to realise"]',3,'The workbook states a self-occupied home is not an investment.',43) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z32-q44','nism-5a-z32','Daily trail commission is calculated as:','["AUM × trail rate p.a. ÷ 365","AUM × trail rate ÷ 12 ÷ 100","NAV × units","Units × face value"]',0,'Paid monthly or quarterly.',44) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z32-q45','nism-5a-z32','Debt-oriented mutual fund gains are taxed at:','["20% STCG only","Slab rates for both short-term and long-term","Nil","12.5% LTCG"]',1,'Per the Sept 2026 workbook.',45) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
