INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z32-q47','nism-5a-z32','With a scheme return of 8%, risk-free 5% and beta 1.2, the Treynor ratio is:','["1.5","3.0","2.5","0.6"]',2,'(8 − 5) ÷ 1.2 = 2.5.',47) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
