INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z32-q49','nism-5a-z32','A Registered Investment Adviser (RIA) cannot:','["Advise on mutual funds","Earn both advisory fees and commission","Use a risk profile","Charge advisory fees"]',1,'Only two transaction types exist: advisory and execution-only.',49) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z32-q50','nism-5a-z32','On a change in control of an AMC, unitholders must be given an exit option at NAV without load for at least:','["30 calendar days","15 days","90 days","7 days"]',0,'Also notice to unitholders and advertisement.',50) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z32-q51','nism-5a-z32','Where a TRI is unavailable for a period, the benchmark return is shown using:','["No benchmark","A composite CAGR: PRI until TRI starts and TRI thereafter","The AMC''s own estimate","The risk-free rate"]',1,'This was permitted for older periods.',51) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
