INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q164','nism-5b-z0','An NAV rising from ₹12 to ₹15 gives a simple return of:','["20%","30%","25%","15%"]',2,'(15 − 12) ÷ 12 = 25%.',164) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q165','nism-5b-z0','An investor redeems 510 units at an NAV of ₹75.80 with an exit load of 1%. The amount received (before tax) is:','["₹38,148.00","₹39,044.58","₹38,658.00","₹38,271.42"]',3,'510 × 75.80 × 0.99.',165) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q166','nism-5b-z0','Product label categories in product literature include:','["Speculation, hedging, arbitrage","Wealth creation, regular income, liquidity","Gold, silver, platinum","Short, medium, long duration only"]',1,'Together with asset class, holding period and risk-o-meter.',166) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q167','nism-5b-z0','An investor invests ₹69,000 in an open-ended scheme at an NAV of ₹56.50. With no entry load, the number of units allotted is:','["6900.000","1194.366","3898500.000","1221.239"]',3,'Units = 69000 ÷ 56.50 = 1221.239.',167) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q168','nism-5b-z0','The dividend option in mutual funds is now called:','["CAS","IDCW","DDT","SWP"]',1,'IDCW = Income Distribution cum Capital Withdrawal.',168) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q169','nism-5b-z0','For liquid and overnight schemes, the cut-off time for purchases is:','["3:00 pm","2:30 pm","1:30 pm","12:00 noon"]',2,'Funds must be available before the cut-off to get the NAV of the day before receipt.',169) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q170','nism-5b-z0','For a Direct plan the ARN box on the application form should carry:','["The AMC''s code","The word \"Direct\"","The RTA code","It is left blank"]',1,'For Regular plans the ARN/RIA number is written.',170) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q171','nism-5b-z0','ELSS investors can claim deduction under Section 80C up to:','["₹1,50,000 under the Old Tax Regime","₹2,50,000 under the New Tax Regime","₹50,000 under any regime","₹5,00,000 under the Old Tax Regime"]',0,'Deduction up to ₹1.5 lakh, Old Tax Regime only.',171) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q172','nism-5b-z0','A SIP Top-up of +10% a year on ₹2,500 gives an instalment in year 2 of:','["₹2,510","₹2,600","₹2,750","₹3,000"]',2,'2,500 × 1.10 = 2,750.',172) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q173','nism-5b-z0','An SWP stands for:','["Standard Withdrawal Payment","Systematic Wealth Plan","Scheme Withdrawal Policy","Systematic Withdrawal Plan"]',3,'It gives regular income and exit load and tax apply.',173) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q174','nism-5b-z0','TER equals:','["Advisory fee only","Entry load + exit load","Base expense ratio + brokerage + transaction cost + statutory levies","Distributor commission only"]',2,'From 1 Apr 2026: BER + execution brokerage + statutory levies such as GST.',174) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q175','nism-5b-z0','The I-Bex sub-indices Si-Bex, Mi-Bex and Li-Bex refer to maturities of:','["0–91 days, 91–365 days and above","1–3 years, 3–7 years and over 7 years","1–2, 2–4 and 4–6 years","Up to 1 year, 1–5 years and 5–10 years"]',1,'They are ICICI Securities indices.',175) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q176','nism-5b-z0','A scheme announces a bonus of 1:2 (one free unit for every 2 units held). An investor holding 400 units will receive:','["800 units","133 units","200 units","400 units"]',2,'Bonus units = 400 ÷ 2.',176) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
