INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q179','nism-5b-z0','Third-party payments for a minor''s investment by parents or related persons are allowed up to:','["₹5,000","₹1,00,000","₹50,000 per purchase or SIP instalment","Any amount"]',2,'A Third Party Declaration and KYC of the payer are required.',179) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
