INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q461','nism-5b-z0','A portfolio of ₹31,00,000 is 70:30 equity:debt. Equity rises 10% and debt is unchanged. To rebalance to the original ratio, the amount of equity to be sold is:','["₹3,10,000","₹65,100","₹2,17,000","₹97,650"]',1,'New equity = 2387000; target = 2321900; sell the excess.',461) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q462','nism-5b-z0','A scheme has total assets of ₹179.40 crore, liabilities (other than to unitholders) of ₹0.80 crore and 1.30 crore units outstanding. Its NAV per unit is:','["₹77.65","₹137.38","₹138.00","₹138.62"]',1,'NAV = (179.40 − 0.80) ÷ 1.30 = ₹137.38.',462) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q463','nism-5b-z0','An investment of ₹63,000 grows to ₹88,361 in 5 years. The compounded annual growth rate (CAGR) is closest to:','["5.0%","7.0%","9.0%","8.1%"]',1,'CAGR = (end/start)^(1/5) − 1 ≈ 7%.',463) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q464','nism-5b-z0','An investor holds 335 units under the IDCW Reinvestment option. IDCW is ₹1 per unit and the ex-IDCW NAV is ₹25. The additional units allotted are:','["12.88","335.00","13.40","26.80"]',2,'Units = (335 × 1) ÷ 25 = 13.40.',464) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q465','nism-5b-z0','An investor redeems 180 units at an NAV of ₹43.20 with an exit load of 1%. The amount received (before tax) is:','["₹7,776.00","₹7,698.24","₹7,596.00","₹7,853.76"]',1,'180 × 43.20 × 0.99.',465) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q466','nism-5b-z0','A scheme announces a bonus of 1:4 (one free unit for every 4 units held). An investor holding 300 units will receive:','["60 units","300 units","75 units","1200 units"]',2,'Bonus units = 300 ÷ 4.',466) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q467','nism-5b-z0','A distributor has ₹57,00,000 of client AUM in regular plans with a trail rate of 1.25% p.a. The approximate daily trail commission is:','["₹5,856.16","₹5,937.50","₹2,342.47","₹195.21"]',3,'Daily trail = AUM × rate ÷ 365 = ₹195.21.',467) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q468','nism-5b-z0','An investor invests ₹1,77,000 in an open-ended scheme at an NAV of ₹80.10. With no entry load, the number of units allotted is:','["17700.000","2209.738","14177700.000","2161.113"]',1,'Units = 177000 ÷ 80.10 = 2209.738.',468) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
